# Using Vicuna Language Model in SwiftUI

Here's a comprehensive guide to integrate Vicuna with SwiftUI:

## Option 1: Using Ollama (Easiest)

### 1. Setup Ollama Locally

```bash
# Install Ollama from ollama.ai
# Then run Vicuna
ollama run vicuna
```

### 2. SwiftUI Implementation

```swift
import SwiftUI

@MainActor
class VicunaViewModel: ObservableObject {
    @Published var userInput: String = ""
    @Published var response: String = ""
    @Published var isLoading: Bool = false

    private let apiURL = "http://localhost:11434/api/generate"

    func generateResponse() {
        isLoading = true

        let requestBody: [String: Any] = [
            "model": "vicuna",
            "prompt": userInput,
            "stream": false
        ]

        guard let jsonData = try? JSONSerialization.data(withJSONObject: requestBody) else {
            isLoading = false
            return
        }

        var request = URLRequest(url: URL(string: apiURL)!)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.httpBody = jsonData

        URLSession.shared.dataTask(with: request) { data, _, error in
            defer { self.isLoading = false }

            guard let data = data else { return }

            do {
                if let json = try JSONSerialization.jsonObject(with: data) as? [String: Any],
                   let response = json["response"] as? String {
                    self.response = response
                }
            } catch {
                self.response = "Error: \(error.localizedDescription)"
            }
        }.resume()
    }
}

struct ContentView: View {
    @StateObject private var viewModel = VicunaViewModel()

    var body: some View {
        VStack(spacing: 16) {
            Text("Vicuna Chat")
                .font(.title)

            TextEditor(text: $viewModel.userInput)
                .border(Color.gray)
                .frame(height: 100)

            Button(action: viewModel.generateResponse) {
                if viewModel.isLoading {
                    ProgressView()
                        .foregroundColor(.white)
                } else {
                    Text("Send")
                }
            }
            .frame(maxWidth: .infinity)
            .padding()
            .background(Color.blue)
            .foregroundColor(.white)
            .disabled(viewModel.isLoading)

            ScrollView {
                Text(viewModel.response)
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding()
            }
            .border(Color.gray)

            Spacer()
        }
        .padding()
    }
}
```

## Option 2: Using llama.cpp with Swift

```swift
import Foundation

class LlamaCppVicuna {
    let process = Process()
    let pipe = Pipe()

    func initialize() {
        process.executableURL = URL(fileURLWithPath: "/path/to/llama.cpp/main")
        process.arguments = [
            "-m", "/path/to/vicuna-model.gguf",
            "--prompt", "Your prompt here"
        ]
        process.standardOutput = pipe

        try? process.run()
    }

    func getOutput() -> String {
        let data = pipe.fileHandleForReading.readDataToEndOfFile()
        return String(data: data, encoding: .utf8) ?? ""
    }
}
```

## Option 3: Using MLX (Apple Silicon)

```swift
import SwiftUI

@MainActor
class MLXVicunaViewModel: ObservableObject {
    @Published var response: String = ""
    @Published var isLoading: Bool = false

    func generateWithMLX(prompt: String) {
        isLoading = true

        DispatchQueue.global().async {
            // Call MLX Python bindings or compiled framework
            let result = self.callMLXModel(prompt: prompt)

            DispatchQueue.main.async {
                self.response = result
                self.isLoading = false
            }
        }
    }

    private func callMLXModel(prompt: String) -> String {
        // Implementation depends on MLX Swift bindings
        return "Response from MLX"
    }
}
```

## Option 4: Using Cloud API

```swift
@MainActor
class CloudVicunaViewModel: ObservableObject {
    @Published var response: String = ""
    @Published var isLoading: Bool = false

    func generateResponse(prompt: String) {
        isLoading = true

        var request = URLRequest(url: URL(string: "https://api.replicate.com/v1/predictions")!)
        request.httpMethod = "POST"
        request.setValue("Token YOUR_API_KEY", forHTTPHeaderField: "Authorization")
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        let body: [String: Any] = [
            "version": "vicuna-model-id",
            "input": ["prompt": prompt]
        ]

        request.httpBody = try? JSONSerialization.data(withJSONObject: body)

        URLSession.shared.dataTask(with: request) { data, _, error in
            defer { self.isLoading = false }

            if let data = data,
               let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
               let output = json["output"] as? String {
                self.response = output
            }
        }.resume()
    }
}
```

## Recommendations

| Method | Pros | Cons |
|--------|------|------|
| **Ollama** | Easiest setup, free | Requires local server |
| **llama.cpp** | Fast, local | Requires compilation |
| **MLX** | Apple optimized | Limited to Apple Silicon |
| **Cloud API** | No local resources | Cost, latency |

**Best for SwiftUI:** Start with **Ollama** for development, then move to **MLX** or cloud APIs for production.

